solution:
static int countVowels(String s) {
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        switch (s.charAt(i)) {
            case 'a', 'e', 'i', 'o', 'u',
                 'A', 'E', 'I', 'O', 'U' -> count++;
            default -> { }
        }
    }
    return count;
}
